using Ambio.Domain.Common;

namespace Ambio.Domain.JobApplications;

/// <summary>An application, to an offer (<see cref="OfferApplication"/>) or spontaneous
/// (<see cref="SpontaneousApplication"/>). Its <see cref="ShortId"/> identifies it in its URL (ADR 0014).</summary>
public abstract class JobApplication : ITimeStampable
{
    public Guid Id { get; } = Guid.CreateVersion7();

    // Random and unique: generated by Infrastructure, which retries while it is taken.
    public required string ShortId
    {
        get;
        init
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(value);
            field = value;
        }
    }

    public ApplicationStatus Status { get; private set; } = ApplicationStatus.Draft;

    public required Channel Channel { get; set; }

    // Free text, such as a generic address like jobs@… or the name of the person who referred the candidate.
    public string? ChannelDetail { get; set; }

    // The day it was sent: null while it is a draft.
    public DateOnly? AppliedOn { get; private set; }

    public string? Notes { get; set; }

    public DateTime CreatedAt { get; set; }

    public DateTime UpdatedAt { get; set; }

    public DateTime? ArchivedAt { get; set; }

    /// <summary>Records that the draft was sent on <paramref name="appliedOn"/>: it moves to
    /// <see cref="ApplicationStatus.Applied"/>.</summary>
    /// <exception cref="InvalidOperationException">The application isn't a draft.</exception>
    public void MarkAsSent(DateOnly appliedOn)
    {
        if (Status != ApplicationStatus.Draft)
        {
            throw new InvalidOperationException($"Only a draft can be sent; this application is {Status}.");
        }

        Status = ApplicationStatus.Applied;
        AppliedOn = appliedOn;
    }

    /// <summary>Corrects the day the application was sent, without changing its status.</summary>
    /// <exception cref="InvalidOperationException">The application hasn't been sent: <see cref="MarkAsSent"/> records
    /// its first sending day.</exception>
    public void ChangeAppliedOn(DateOnly appliedOn)
    {
        if (AppliedOn is null)
        {
            throw new InvalidOperationException("Only a sent application has a sending day to change.");
        }

        AppliedOn = appliedOn;
    }
}
